const tabId = 480038410;
const audiobooks = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/audiobooks/"]'));
  const results = [];
  links.forEach(a => {
    if (a.href.match(/\/audiobooks\/\d+\//)) {
      const text = a.textContent.trim().replace(/\s+/g, ' ');
      const card = a.closest('.item-card, .card, li, div');
      results.push({
        href: a.href,
        text: text,
        cardText: card?.textContent?.trim().replace(/\s+/g, ' ')
      });
    }
  });
  return results.slice(0, 10);
});
